    if(obj.id==='nav-schedule') return ref('7. ТИЖНЕВИЙ ГРАФІК ТИСКУ','#schedule','3.1–3.5; 7');
    if(obj.id==='nav-journal' || /-b-journal$/.test(obj.id)) return ref('9. ЖУРНАЛ ПОДІЙ','#events','3.1–3.5; 9');
